row(19, 18, 'MATERIAL', f'AND THE JUDGES SHALL INQUIRE WELL, AND BEHOLD, THE WITNESS IS A FALSE WITNESS, HE TESTIFIED FALSELY AGAINST HIS BROTHER. {HP(19, 18, (("ודרשו", "השפטים", "היטב"), "and the judges shall inquire well — the seven investigations (190:7)"), (("עד", "שקר", "העד"), "the witness is a false witness — the Decalogue\'s word"), (("שקר", "ענה", "באחיו"), "he testified falsely against his brother"))} {AP(19, 18, (("ויתבעון", "דיניא", "יאות"), "AND THE JUDGES SHALL SEEK WELL"), (("סהיד", "שקר", "סהדא", "שקרא", "אסהד", "באחוהי"), "a false witness — the witness testified falsely against his brother"))} THE INQUIRY (190:7-9). Fresh.')
